        void RefreshAnalysisSummaryOnMainThread()
        {
            if (DataAnalysisSummaryLabel == null) return;

            if (!AnalysisInputsAreReady() || !Workspace.IsReady)
            {
                DataAnalysisSummaryLabel.StringValue = "No analysis ready";
                return;
            }

            var context = inspectorPreviewContext ?? Workspace.Context;
            var summary = AnalysisContextSummaryPresentation.BuildText(context);
            var violations = Workspace.Context.DetectInitialParameterLimitViolations();
            if (violations.Count > 0)
            {
                var first = violations[0];
                var subject = string.IsNullOrWhiteSpace(first.ExperimentName)
                    ? first.DisplayName
                    : $"{first.DisplayName} ({first.ExperimentName})";
                var formatted = AnalysisITC.UI.MacOS.CustomViews.AnalysisInspectorDisplayCatalog.FormatParameter(first.Parameter, first.StartingValue);
                var range = AnalysisITC.UI.MacOS.CustomViews.AnalysisInspectorDisplayCatalog.FormatParameterRange(
                    new Parameter(first.Parameter, first.StartingValue));
                summary = $"Fit blocked: {violations.Count} starting value(s) outside {InitialParameterLimitViolationDetector.ActivePolicyName} Limits. First: {subject} = {formatted}, allowed {range}. Edit, restore defaults, or widen Limits.\n\n{summary}";
            }
            DataAnalysisSummaryLabel.StringValue = summary;
        }

        bool AnalysisInputsAreReady()
        {
            var requiredData = Workspace.Session.IsGlobal
                ? DataManager.IncludedData.ToList()
                : DataManager.Current == null
                    ? new List<ExperimentData>()
                    : new List<ExperimentData> { DataManager.Current };

            return requiredData.Count > 0
                && (!Workspace.Session.IsGlobal || requiredData.Count > 1)
                && requiredData.All(AnalysisBuilder.IsAnalysisReady);
        }

        void RebuildInspectorEditorViews()
        {
            ClearInspectorRows();
            inspectorDraft = null;
            inspectorPreviewContext = null;
            activeInspectorDraftKey = null;

            if (!Workspace.IsReady)
            {
                UpdateInspectorSectionVisibility(false, false, false);
                return;
            }

            var draftKey = CreateInspectorDraftKey();
            if (!inspectorDraftCache.TryGetValue(draftKey, out inspectorDraft))
            {
                inspectorDraft = AnalysisInspectorDraft.FromContext(
                    Workspace.Context,
                    Workspace.Session);
                inspectorDraftCache[draftKey] = inspectorDraft;
            }
            else
            {
                inspectorDraft.MergeContext(
                    Workspace.Context,
                    Workspace.Session);
            }
            activeInspectorDraftKey = draftKey;
            RebuildInspectorRowsFromDraft();
        }

        AnalysisInspectorDraftKey CreateInspectorDraftKey()
        {
            var experiments = Workspace.Session.IsGlobal
                ? DataManager.Data.Where(data => data.Include)
                : new[] { DataManager.Current }.Where(data => data != null);
            return AnalysisInspectorDraftKey.Create(
                Workspace.Session.ModelType,
                Workspace.Session.IsGlobal,
                experiments);
        }

        void PruneInspectorDraftCache()
        {
            if (inspectorDraftCache.Count == 0) return;

            var availableExperimentIds = new HashSet<string>(
                DataManager.Data
                    .Where(data => data != null)
                    .Select(data => data.UniqueID),
                StringComparer.Ordinal);
            var staleKeys = inspectorDraftCache.Keys
                .Where(key => !key.ReferencesOnly(availableExperimentIds))
                .ToList();
            foreach (var key in staleKeys)
                inspectorDraftCache.Remove(key);

            if (activeInspectorDraftKey.HasValue
                && !activeInspectorDraftKey.Value.ReferencesOnly(
                    availableExperimentIds))
            {
                activeInspectorDraftKey = null;
                inspectorDraft = null;
                inspectorPreviewContext = null;
            }
        }

        void RebuildInspectorRowsFromDraft()
        {
            ClearInspectorRows();

            if (!Workspace.IsReady || inspectorDraft == null)
            {
                inspectorPreviewContext = null;
                UpdateInspectorSectionVisibility(false, false, false);
                return;
            }

            inspectorPreviewContext = BuildInspectorPreviewContext() ?? Workspace.Context;
            var context = inspectorPreviewContext;

            var options = inspectorDraft.Options.Values
                .OrderBy(option =>
                    AnalysisInspectorDisplayCatalog.OptionOrder(option.Option.Key))
                .ToList();
            for (var i = 0; i < options.Count; i++)
            {
                var control = AnalysisInspectorRowFactory.Option(
                    options[i],
                    inspectorDraft.Options,
                    SelectedExperimentsHaveAttribute,
                    i < options.Count - 1);
                control.StructureChanged += OnInspectorStructureChanged;
                optionControls.Add(control);
                AddFullWidthArrangedSubview(ModelOptionsStackView, control);
            }

            if (Workspace.Session.IsGlobal)
            {
                var constraints = context.ExposedConstraintFamilies.ToList();
                if (constraints.Count == 0)
                {
                    constraints = context.ExposedConstraintOptions
                        .Select(option => new GlobalConstraintFamilyDescriptor(
                            option.Key,
                            new[] { option.Key },
                            option.Value))
                        .ToList();
                }
                for (var i = 0; i < constraints.Count; i++)
                {
                    var descriptor = constraints[i];
                    var showSiteIndex = !descriptor.IsFamily && constraints.Count(other =>
                        other.Key.GetProperties().ParentType
                        == descriptor.Key.GetProperties().ParentType) > 1;
                    var control = AnalysisInspectorRowFactory.Constraint(
                        descriptor,
                        inspectorDraft,
                        showSiteIndex,
                        false);
                    control.StructureChanged += OnInspectorStructureChanged;
                    constraintControls.Add(control);
                    AddFullWidthArrangedSubview(ConstraintStackView, control);
                }
            }

            var parameters = context.ExposedParameters.ToList();
            for (var i = 0; i < parameters.Count; i++)
            {
                var parameter = parameters[i];
                var parameterDraft = inspectorDraft.GetOrCreateParameter(
                    parameter,
                    Workspace.Session);
                var showSiteIndex = parameters.Count(other =>
                    other.Key.GetProperties().ParentType
                    == parameter.Key.GetProperties().ParentType) > 1;
                var control = AnalysisInspectorRowFactory.Parameter(
                    parameter,
                    parameterDraft,
                    inspectorDraft.Options,
                    showSiteIndex);
                control.FittingDimensionsChanged += OnInspectorFittingDimensionsChanged;
                parameterControls.Add(control);
                AddFullWidthArrangedSubview(ParameterStackView, control);

                if (i < parameters.Count - 1)
                {
                    var separator = CreateParameterSeparator();
                    parameterSeparators.Add(separator);
                    AddFullWidthArrangedSubview(ParameterStackView, separator);
                }
            }

            UpdateInspectorSectionVisibility(
                parameterControls.Count > 0,
                constraintControls.Count > 0,
                optionControls.Count > 0);

            ParameterStackView.Layout();
            ConstraintStackView.Layout();
            ModelOptionsStackView.Layout();
        }

        static void AddFullWidthArrangedSubview(NSStackView stackView, NSView view)
        {
            view.TranslatesAutoresizingMaskIntoConstraints = false;
            stackView.AddArrangedSubview(view);
            stackView.AddConstraint(NSLayoutConstraint.Create(
                view,
                NSLayoutAttribute.Width,
                NSLayoutRelation.Equal,
                stackView,
                NSLayoutAttribute.Width,
                1,
                0));
        }

        static NSView CreateParameterSeparator()
        {
            var container = new NSView
            {
                TranslatesAutoresizingMaskIntoConstraints = false,
            };
            container.AddConstraint(NSLayoutConstraint.Create(
                container,
                NSLayoutAttribute.Height,
                NSLayoutRelation.Equal,
                1,
                12));

            var separator = new NSBox
            {
                BoxType = NSBoxType.NSBoxSeparator,
                TranslatesAutoresizingMaskIntoConstraints = false,
            };
            container.AddSubview(separator);
            container.AddConstraints(new[]
            {
                NSLayoutConstraint.Create(
                    separator,
                    NSLayoutAttribute.Leading,
                    NSLayoutRelation.Equal,
                    container,
                    NSLayoutAttribute.Leading,
                    1,
                    0),
                NSLayoutConstraint.Create(
                    separator,
                    NSLayoutAttribute.Trailing,
                    NSLayoutRelation.Equal,
                    container,
                    NSLayoutAttribute.Trailing,
                    1,
                    0),
                NSLayoutConstraint.Create(
                    separator,
                    NSLayoutAttribute.CenterY,
                    NSLayoutRelation.Equal,
                    container,
                    NSLayoutAttribute.CenterY,
                    1,
                    0),
            });
            return container;
        }

