        void ClearInspectorRows()
        {
            foreach (var control in parameterControls)
            {
                control.FittingDimensionsChanged -= OnInspectorFittingDimensionsChanged;
                ParameterStackView.RemoveView(control);
                control.Dispose();
            }
            parameterControls.Clear();

            foreach (var separator in parameterSeparators)
            {
                ParameterStackView.RemoveView(separator);
                separator.Dispose();
            }
            parameterSeparators.Clear();

            foreach (var control in optionControls)
            {
                ModelOptionsStackView.RemoveView(control);
                control.Dispose();
            }
            optionControls.Clear();

            foreach (var control in constraintControls)
            {
                ConstraintStackView.RemoveView(control);
                control.Dispose();
            }
            constraintControls.Clear();
        }

        AnalysisContext BuildInspectorPreviewContext()
        {
            if (inspectorDraft == null) return Workspace.Context;

            NormalizeSequentialInspectorDraft();

            try
            {
                var previewSession = CloneAnalysisSession(Workspace.Session);
                var state = previewSession.Active;

                state.ModelOptions.Clear();
                foreach (var option in inspectorDraft.Options)
                    state.ModelOptions[option.Key] = option.Value.Option.Copy();

                state.Constraints.Clear();
                foreach (var constraint in inspectorDraft.Constraints)
                    state.Constraints[constraint.Key] = constraint.Value;

                foreach (var parameter in inspectorDraft.Parameters.Values)
                {
                    var key = new ParameterOverrideKey(
                        previewSession.ModelType,
                        parameter.Key);
                    if (!parameter.HasOverride)
                    {
                        state.ParameterOverrides.Remove(key);
                        continue;
                    }

                    state.ParameterOverrides[key] = new ParameterOverride
                    {
                        Value = parameter.InternalValue,
                        IsLocked = parameter.Locked,
                    };
                }

                var experiments = previewSession.IsGlobal
                    ? DataManager.Data.Where(data => data.Include)
                    : new[] { DataManager.Current }.Where(data => data != null);
                return AnalysisBuilder.Build(
                    previewSession,
                    experiments,
                    reuseAttachedSolutionInitialValues: true);
            }
            catch (Exception ex)
            {
                AppEventHandler.Print(
                    "[Analysis Inspector] Preview rebuild failed: " + ex.Message,
                    1);
                return Workspace.Context;
            }
        }

        static AnalysisSessionState CloneAnalysisSession(AnalysisSessionState source)
        {
            var clone = AnalysisSessionState.CreateDefault();
            clone.ModelType = source.ModelType;
            clone.IsGlobal = source.IsGlobal;
            CopyAnalysisState(source.Single, clone.Single);
            CopyAnalysisState(source.Global, clone.Global);
            return clone;
        }

        static void CopyAnalysisState(AnalysisState source, AnalysisState target)
        {
            foreach (var option in source.ModelOptions)
                target.ModelOptions[option.Key] = option.Value.Copy();
            foreach (var constraint in source.Constraints)
                target.Constraints[constraint.Key] = constraint.Value;
            foreach (var parameter in source.ParameterOverrides)
            {
                target.ParameterOverrides[parameter.Key] = new ParameterOverride
                {
                    Value = parameter.Value.Value,
                    IsLocked = parameter.Value.IsLocked,
                };
            }
        }

        bool SelectedExperimentsHaveAttribute(AttributeKey key)
        {
            var experiments = Workspace.Session.IsGlobal
                ? DataManager.Data.Where(data => data.Include)
                : new[] { DataManager.Current }.Where(data => data != null);
            var selected = experiments.ToList();
            return selected.Count > 0
                && selected.All(data =>
                    data.Attributes.Exists(attribute => attribute.Key == key));
        }

        bool ApplyInspectorSettings()
        {
            var invalidParameter = parameterControls.FirstOrDefault(control =>
                control.IsApplicable && !control.HasValidInput);
            if (invalidParameter != null)
            {
                ShowInspectorTab(1);
                invalidParameter.FocusInput();
                StatusBarManager.SetStatus("Enter a valid parameter value before fitting");
                return false;
            }

            var invalidOption = optionControls.FirstOrDefault(control =>
                control.IsApplicable && !control.HasValidInput);
            if (invalidOption != null)
            {
                ShowInspectorTab(2);
                invalidOption.FocusInput();
                StatusBarManager.SetStatus("Enter a valid model option before fitting");
                return false;
            }

            FittingOptionsController.ErrorEstimationMethod =
                (ErrorEstimationMethod)(int)ErrorMethodControl.IndexOfSelectedItem;
            FittingOptionsController.BootstrapIterations =
                (int)Math.Pow(10, ErrorIterationsControl.DoubleValue);
            FittingOptionsController.IncludeConcentrationVariance =
                IncludeConcErrorControl.State == NSCellStateValue.On;
            FittingOptionsController.EnableAutoConcentrationVariance = false;
            FittingOptionsController.Algorithm =
                (SolverAlgorithm)(int)SolverAlgorithmControl.IndexOfSelectedItem;
            FittingOptionsController.UseErrorWeightedFitting = UseWeightedControl.State == NSCellStateValue.On;
            FittingOptionsController.UnlockBootstrapParameters =
                UnlockParametersForErrorEstimationControl.State == NSCellStateValue.On;

            if (inspectorDraft == null) return true;

            NormalizeSequentialInspectorDraft();

            Workspace.ReplaceModelOptions(
                inspectorDraft.Options.ToDictionary(
                    option => option.Key,
                    option => option.Value.Option.Copy()),
                rebuild: false);

            foreach (var constraint in inspectorDraft.Constraints)
                Workspace.SetConstraint(
                    constraint.Key,
                    constraint.Value,
                    rebuild: false);

            foreach (var parameter in inspectorDraft.Parameters.Values)
            {
                if (!parameter.HasOverride)
                    Workspace.ResetParameterOverride(parameter.Key, rebuild: false);
                else
                    Workspace.SetParameterOverride(
                        parameter.Key,
                        parameter.InternalValue,
                        parameter.Locked,
                        rebuild: false);
            }

            if (!Workspace.TryRebuild())
            {
                StatusBarManager.SetStatus("Unable to rebuild the analysis with these settings");
                return false;
            }
            return true;
        }

        void NormalizeSequentialInspectorDraft()
        {
            if (inspectorDraft == null
                || Workspace.Session.ModelType != AnalysisModel.SequentialBindingSites
                || !inspectorDraft.Options.TryGetValue(
                    AttributeKey.SequentialSiteCount,
                    out var countOption))
                return;

            inspectorDraft.NormalizeSequentialShape(
                countOption.Option.IntValue,
                normalizeConstraints: Workspace.Session.IsGlobal);
        }

        void ShowInspectorTab(int index)
        {
            AnalysisInspectorTabControl.SelectedSegment = index;
            AnalysisInspectorTabView.SelectAt(index);
            AnalysisInspectorTabView.LayoutSubtreeIfNeeded();
        }

        // ── Fitting ────────────────────────────────────────────────────────

        void RunFit()
        {
            if (!AnalysisBuilder.IsModelAvailable(ModelFromControl, IsGlobalMode))
            {
                AppEventHandler.DisplayHandledException(new HandledException(
                    HandledException.Severity.Message,
                    "Model Not Available",
                    "The current data selection does not support analysis using the selected model"));
                return;
            }

            try
            {
                // Ensure we have a context even if no data-change event fired yet
                if (!Workspace.IsReady) Workspace.Rebuild();

                if (!ApplyInspectorSettings()) return;

                AppEventHandler.PrintAndLog("Start Analysis");
                var solver = Workspace.PrepareForSolve();
                solver.SolverAlgorithm = FittingOptionsController.Algorithm;
                solver.ErrorEstimationMethod = FittingOptionsController.ErrorEstimationMethod;
                solver.BootstrapIterations = FittingOptionsController.BootstrapIterations;
                solver.UseErrorWeightedFitting = FittingOptionsController.UseErrorWeightedFitting;

                // Enter the fitting state only after preflight succeeds. An
                // out-of-range automatic or reused value therefore keeps Run Fit
                // available and leaves the inspector values unchanged.
                isFitting = true;
                ToggleFitButtons(false);

                solver.Analyze();

                // Persist converged values so the next rebuild starts from the fit result,
                // but do NOT rebuild now — the current context IS the fitted model.
                // Workspace.PersistFittedParameters(); TODO figure out if this is relevant
            }
            catch (Exception ex)
            {
                if (ex is InitialParameterLimitException limitException)
                    FocusFirstInitialLimitViolation(limitException);
                AppEventHandler.DisplayHandledException(ex);
                StatusBarManager.ClearAppStatus();
                isFitting = false;
                ToggleFitButtons(true);
            }
        }

        void FocusFirstInitialLimitViolation(InitialParameterLimitException exception)
        {
            var violation = exception.Violations.FirstOrDefault(item =>
                parameterControls.Any(control => control.ParameterKey == item.Parameter));
            if (violation == null) return;

            var control = parameterControls.First(item => item.ParameterKey == violation.Parameter);
            ShowInspectorTab(1);
            control.FocusInput();
        }

        // ── Solver event handlers ──────────────────────────────────────────

        void OnAnalysisFinished(object sender, SolverConvergence e)
        {
            AppEventHandler.PrintAndLog("Analysis Ended: " + e.Termination, 0);
            AppEventHandler.PrintAndLog("Iterations: " + e.Iterations, 1);
            AppEventHandler.PrintAndLog("Time: " + e.Time.TotalMilliseconds + "ms", 1);
            AppEventHandler.PrintAndLog("Error Time: " + e.ErrorEstimationTime.TotalMilliseconds + "ms", 1);
            AppEventHandler.PrintAndLog("Message: " + e.Message, 1);
            AppEventHandler.PrintAndLog("Failure Reason: " + e.FailureReason, 1);
            AppEventHandler.PrintAndLog("Error Summary: " + e.ErrorEstimationSummary, 1);
            AppEventHandler.PrintAndLog("Error Estimation: " + e.ErrorEstimationOutcome, 1);
            AppEventHandler.PrintAndLog("Stopped: " + e.Stopped, 1);
            AppEventHandler.PrintAndLog("Failed:  " + e.Failed, 1);

            StatusBarManager.ClearAppStatus();
            StatusBarManager.QueueStatus($"{e.Message}", 3000);
            StatusBarManager.QueueStatus($"{e.Iterations} iterations | {TimeUnitAttribute.FormatTimeSpanShort(e.TotalTime)}", 3000);
            if (e.Success) StatusBarManager.QueueStatus($"{e.Algorithm.GetProperties().ShortName} | RMSD = {e.Loss:G4}", 2000);
            if (e.ErrorEstimationOutcome != ErrorEstimationOutcome.None) StatusBarManager.QueueStatus($"{e.ErrorEstimationSummary}", 2000);
            var boundaryWarning = ParameterBoundaryWarningFormatter.Format(
                e.ParameterBoundaryContacts);
            if (!string.IsNullOrWhiteSpace(boundaryWarning))
                StatusBarManager.QueueStatus(boundaryWarning, 5000);

            GraphView.Invalidate();
            RefreshFitSummary();
            isFitting = false;
            ToggleFitButtons(true);
        }

        void OnErrorIteration(object sender, Tuple<int, int, float> e)
        {
            StatusBarManager.SetProgress(e.Item3);
            StatusBarManager.SetStatus("Estimating Errors...", 0, 2);
            StatusBarManager.SetSecondaryStatus(e.Item1 + "/" + e.Item2, 0);
        }

        // ── Misc ───────────────────────────────────────────────────────────

        void OnPrintOperation(object sender, EventArgs e)
        {
            if (StateManager.CurrentState != ProgramState.Analyze) return;
            GraphView.Print();
        }

        void RefreshGlobalModeControls()
        {
            var canUseGlobalMode = ActiveExperimentCount > 1;

            if (!canUseGlobalMode && IsGlobalMode)
            {
                AnalysisModeControl.SelectedSegment = 0;
                Workspace.SetGlobalMode(false);
            }

            AnalysisModeControl.SetEnabled(canUseGlobalMode, 1);
            PublishAnalysisMode();
            RefreshAnalysisResultCreationControl();
            RefreshModelAvailability();
        }

        void RefreshAnalysisResultCreationControl()
        {
            if (CreateAnalysisResultControl == null) return;

            var canCreateResult = !IsGlobalMode || ActiveExperimentCount > 1;
            var createResult = IsGlobalMode
                ? AppSettings.CreateGlobalAnalysisResult
                : AppSettings.CreateSingleAnalysisResult;

            CreateAnalysisResultControl.Enabled = canCreateResult;
            CreateAnalysisResultControl.State = createResult
                ? NSCellStateValue.On
                : NSCellStateValue.Off;
            CreateAnalysisResultControl.ToolTip = canCreateResult
                ? "Create a saved analysis result after a successful fit."
                : "Multi analysis results require at least two active data sets.";
        }

        void PublishAnalysisMode()
        {
            var isGlobal = IsGlobalMode;
            if (CurrentAnalysisModeIsGlobal == isGlobal) return;

            CurrentAnalysisModeIsGlobal = isGlobal;
            AnalysisModeDidChange?.Invoke(this, EventArgs.Empty);
        }

        void RefreshModelAvailability()
        {
            if (ModelTypeControl?.Menu == null) return;

            foreach (var item in ModelTypeControl.Items())
            {
                var model = (AnalysisModel)(int)item.Tag;
                item.Enabled = AnalysisBuilder.IsModelAvailable(model, IsGlobalMode);
            }

            ToggleFitButtons(true);
        }

        void ConfigureModelTypeControl()
        {
            if (ModelTypeControl?.Menu == null) return;

            var selectedModel = Workspace.Session.ModelType;
            ModelTypeControl.Menu.RemoveAllItems();
            foreach (var model in AnalysisModelAttribute.GetAll())
            {
                var properties = model.GetProperties();
                ModelTypeControl.Menu.AddItem(new NSMenuItem(ModelMenuTitle(model))
                {
                    Tag = (int)model,
                    ToolTip = properties.Description,
                });
            }

            var selectedItem = ModelTypeControl.Items()
                .FirstOrDefault(item => (AnalysisModel)(int)item.Tag == selectedModel);
            if (selectedItem != null)
                ModelTypeControl.SelectItem(selectedItem);
        }

        static string ModelMenuTitle(AnalysisModel model)
        {
            return model switch
            {
                AnalysisModel.OneSetOfSites => "One Set of Sites",
                AnalysisModel.TwoSetsOfSites => "Two Sets of Sites",
                AnalysisModel.SequentialBindingSites => "Sequential Binding Sites",
                AnalysisModel.CompetitiveBinding => "Competitive Binding",
                AnalysisModel.Dissociation => "Dissociation",
                _ => model.GetProperties().Name,
            };
        }

        void ToggleFitButtons(bool enable)
        {
            bool canFit = enable && !isFitting && CanRunFit();
            FitSimplexButton.Enabled = canFit;
        }

        bool CanRunFit()
        {
            return AnalysisBuilder.IsModelAvailable(ModelFromControl, IsGlobalMode);
        }

        // ── Cleanup ────────────────────────────────────────────────────────

        bool _eventsUnsubscribed;

        void UnsubscribeEvents()
        {
            if (_eventsUnsubscribed) return;
            _eventsUnsubscribed = true;

            Workspace.ContextRebuilt -= OnContextRebuilt;
            Workspace.ContextInvalidated -= OnContextRebuilt;
            SolverInterface.AnalysisFinished -= OnAnalysisFinished;
            SolverInterface.ErrorEstimationIterationCompleted -= OnErrorIteration;
            DataManager.SelectionDidChange -= OnSelectionChanged;
            DataManager.DataDidChange -= OnDataChanged;
            DataManager.DataInclusionDidChange -= OnDataChanged;
            AnalysisGraphView.ParameterSummaryDidChange -= OnParameterSummaryDidChange;
            ErrorMethodControl.Activated -= OnErrorMethodActivated;
            if (summaryExperiment != null)
            {
                summaryExperiment.SolutionChanged -= OnSummaryExperimentSolutionChanged;
                summaryExperiment.InjectionIncludeChanged -= OnSummaryExperimentInjectionIncludeChanged;
            }
            AppDelegate.StartPrintOperation -= OnPrintOperation;
            AppSettings.SettingsDidUpdate -= OnSettingsDidUpdate;
            ResetStoredAnalysisStateRequested -= OnResetStoredAnalysisStateRequested;
        }

        protected override void Dispose(bool disposing)
        {
            if (disposing) UnsubscribeEvents();

            base.Dispose(disposing);
        }
    }
}
